using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

[TestClass]
public class ChatEvals
{
    private static ReportingConfiguration? s_reportingConfiguration;

    [AssemblyInitialize]
    public static void Initialize(TestContext context)
    {
        s_reportingConfiguration = new ReportingConfiguration(
            [
                new CoherenceEvaluator(),
                new RelevanceEvaluator(),
                new FluencyEvaluator(),
                new GroundednessEvaluator(),
            ],
            chatClientFactory: CreateChatClient,
            reportStorageFactory: () => new DiskBasedReportStorage("eval-results"));
    }

    [AssemblyCleanup]
    public static async Task Cleanup()
    {
        if (s_reportingConfiguration is not null)
        {
            await s_reportingConfiguration.DisposeAsync();
        }
    }

    private static IChatClient CreateChatClient(ChatConfiguration chatConfiguration)
    {
        var builder = Host.CreateApplicationBuilder();
        builder.AddAzureOpenAIChatClient("chat");
        var host = builder.Build();
        return host.Services.GetRequiredService<IChatClient>();
    }

    [TestMethod]
    public async Task Chat_responds_coherently_to_greeting()
    {
        await using var scenario = await s_reportingConfiguration!.CreateScenarioRunAsync(
            nameof(Chat_responds_coherently_to_greeting));

        var chatClient = scenario.ChatClient!;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Hello, how can you help me today?")
        };

        var response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);

        scenario.AssertAllMetricsPassed();
    }

    [TestMethod]
    public async Task Chat_provides_relevant_answer()
    {
        await using var scenario = await s_reportingConfiguration!.CreateScenarioRunAsync(
            nameof(Chat_provides_relevant_answer));

        var chatClient = scenario.ChatClient!;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);

        scenario.AssertAllMetricsPassed();
    }

    [TestMethod]
    public async Task Chat_handles_follow_up_questions()
    {
        await using var scenario = await s_reportingConfiguration!.CreateScenarioRunAsync(
            nameof(Chat_handles_follow_up_questions));

        var chatClient = scenario.ChatClient!;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Tell me about renewable energy."),
        };

        var response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        messages.Add(new ChatMessage(ChatRole.User, "What are the main advantages of solar power specifically?"));

        response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);

        scenario.AssertAllMetricsPassed();
    }
}

